// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** An entry of the hospital's list of what to report (MSDS CQI 106 i). */
export interface IncidentTypeOut {
  type_code: string;
  name: string;
  area: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational";
  /** Always: a sentinel event whenever it happened; IfSevereHarm: only with severe harm or a death */
  sentinel: "Always" | "IfSevereHarm";
  description: string | null;
  sort_order: number;
  is_active: boolean;
  row_version: number;
}

export interface IncidentIn {
  /** From GET /incident-types */
  type_code: string;
  /** NearMiss: caught before it reached anyone */
  kind?: "Incident" | "NearMiss";
  harm?: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death";
  occurred_at: string;
  affected: "Patient" | "Staff" | "Visitor" | "None";
  patient_id?: number | null;
  /** The admission it happened in (the patient follows from it) */
  admission_id?: number | null;
  /** The staff member harmed (affected Staff) */
  employee_id?: number | null;
  /** A theatre adverse event: the operation (with ot_phase) */
  booking_id?: number | null;
  ot_phase?: "BeforeInduction" | "Induction" | "Maintenance" | "Emergence" | "Recovery" | "AfterRecovery" | null;
  /** A medication error or an adverse drug reaction: the medicine */
  drug_id?: number | null;
  medication_stage?: "Prescribing" | "Transcribing" | "Dispensing" | "Administration" | "Monitoring" | null;
  /** An unexpected death: the death record */
  death_id?: number | null;
  department_id?: number | null;
  ward_id?: number | null;
  location?: string | null;
  /** What happened: facts, not opinions or blame */
  description: string;
  /** What was done at once for the person and to make the place safe */
  immediate_action: string;
  /** Reporting what the screening list found (GET /incident-screening) */
  screening_key?: string | null;
  /** Only the incident managers see who reported it */
  reporter_confidential?: boolean;
}

